/**
 * Shared pieces for the resumable document upload integration tests: request builders that drive
 * the route handlers directly, a lazily generated byte stream, and a tenant/ticket fixture.
 */
import { randomUUID } from 'node:crypto';
import { NextRequest } from 'next/server';
import type { Knex } from 'knex';
import { tenantDb } from '@alga-psa/db';

export const MiB = 1024 * 1024;

/** Byte at global position `pos` of every generated file: pos & 255 (so any slice can be verified). */
const PATTERN_BLOCK = Buffer.alloc(64 * 1024);
for (let i = 0; i < PATTERN_BLOCK.length; i++) PATTERN_BLOCK[i] = i & 255;

export function patternBuffer(start: number, length: number): Buffer {
  const out = Buffer.allocUnsafe(length);
  for (let i = 0; i < length; i++) out[i] = (start + i) & 255;
  return out;
}

export function matchesPattern(buffer: Buffer, start = 0): boolean {
  for (let i = 0; i < buffer.length; i++) if (buffer[i] !== ((start + i) & 255)) return false;
  return true;
}

/**
 * A body of `length` bytes produced on demand in 64 KiB blocks (start must be a multiple of 256).
 * `state.pulled` counts bytes the consumer has actually read, so a test can prove a rejected chunk
 * was abandoned mid-stream instead of being read to the end.
 */
export function generatedBody(length: number, options: { failAfter?: number } = {}) {
  const state = { pulled: 0 };
  const body = new ReadableStream<Uint8Array>({
    pull(controller) {
      if (options.failAfter !== undefined && state.pulled >= options.failAfter) {
        controller.error(new Error('connection dropped'));
        return;
      }
      const remaining = length - state.pulled;
      if (remaining <= 0) return controller.close();
      const size = Math.min(PATTERN_BLOCK.length, remaining);
      state.pulled += size;
      controller.enqueue(size === PATTERN_BLOCK.length ? PATTERN_BLOCK : PATTERN_BLOCK.subarray(0, size));
    },
  }, { highWaterMark: 0 });
  return { body, state };
}

export function request(
  method: string,
  path: string,
  options: { headers?: Record<string, string>; json?: unknown; body?: ReadableStream<Uint8Array> | Buffer } = {},
): NextRequest {
  const headers = new Headers(options.headers);
  let body: BodyInit | undefined;
  if (options.json !== undefined) {
    headers.set('content-type', 'application/json');
    body = JSON.stringify(options.json);
  } else if (options.body) {
    body = options.body as BodyInit;
  }
  return new NextRequest(`http://localhost${path}`, { method, headers, body, duplex: 'half' } as RequestInit);
}

export function contentRange(start: number, length: number, total: number): Record<string, string> {
  return {
    'content-range': `bytes ${start}-${start + length - 1}/${total}`,
    'content-length': String(length),
    'content-type': 'application/octet-stream',
  };
}

export interface UploadFixture {
  tenant: string;
  uploader: string;
  otherUser: string;
  client: string;
  ticket: string;
}

/** A committed tenant with an internal uploader, a second user, a client and a ticket. */
export async function createUploadFixture(db: Knex): Promise<UploadFixture> {
  const f: UploadFixture = {
    tenant: randomUUID(), uploader: randomUUID(), otherUser: randomUUID(), client: randomUUID(), ticket: randomUUID(),
  };
  await tenantDb(db, f.tenant).unscoped('tenants', 'create isolated upload test tenant')
    .insert({ tenant: f.tenant, client_name: 'Upload tests', email: 'tenant@example.test', product_code: 'psa' });
  const table = (name: string) => tenantDb(db, f.tenant).table(name);
  await table('clients').insert({ tenant: f.tenant, client_id: f.client, client_name: 'Upload client' });
  await table('users').insert([
    { tenant: f.tenant, user_id: f.uploader, username: f.uploader, email: 'up@example.test', hashed_password: 'unused', user_type: 'internal', is_inactive: false },
    { tenant: f.tenant, user_id: f.otherUser, username: f.otherUser, email: 'other@example.test', hashed_password: 'unused', user_type: 'internal', is_inactive: false },
  ]);
  await table('tickets').insert({ tenant: f.tenant, ticket_id: f.ticket, ticket_number: 'UP-1', client_id: f.client, title: 'Upload ticket', entered_by: f.uploader });
  return f;
}

export async function dropUploadFixture(db: Knex, f: UploadFixture): Promise<void> {
  const table = (name: string) => tenantDb(db, f.tenant).table(name);
  const docs = await table('documents').select('document_id', 'file_id');
  await table('document_upload_sessions').delete();
  await table('document_associations').delete();
  await table('documents').delete();
  await table('external_files').delete();
  void docs;
  await table('tickets').delete();
  await table('users').delete();
  await table('clients').delete();
  await tenantDb(db, f.tenant).unscoped('tenants', 'remove isolated upload test tenant').where({ tenant: f.tenant }).delete();
}
